tests.code:
const s = getComputedStyle(document.querySelector('.dot')); assert(s.animationName === 'pulse', "expected animation name 'pulse', got " + s.animationName);
assert(s.animationDuration === '1s', "expected duration 1s, got " + s.animationDuration);
assert(s.animationIterationCount === 'infinite', "expected infinite, got " + s.animationIterationCount);

solution:
@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.1); }
  100% { transform: scale(1); }
}
.dot {
  animation: pulse 1s infinite;
}

